Lemma mem_ok_mem (M M1 : word -> option byte) (LBo : list (Z * Z)) LK cr Aw model (dst len : Z) :
  ri_inv HI (LBo ++ LB) FF LK cr Aw M (vml_of model) -> mem_ok M ->
