Lemma accA_mem (M M1 : word -> option byte) (LB' : list (Z * Z)) (dst len q A : Z) :
  (forall a, 0 <= a < 2 ^ 64 -> aclient L ar LB' FF (S - 80) 2560 a -> ~ (dst <= a < dst + len) -> M1 (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
